"use server";

import { createClient } from "@/lib/supabase-server";
import { getFriendlyErrorMessage, logLedgerEntry } from "@/lib/action-utils";
import { revalidatePath } from "next/cache";

export async function upsertBudget(formData: {
  category: string;
  amount: number;
  period_month: number;
  period_year: number;
}) {
  try {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return { error: "Not authenticated" };

    const { error } = await supabase
      .from("budgets")
      .upsert([{ ...formData, user_id: user.id }], {
        onConflict: "user_id,category,period_month,period_year"
      });

    if (error) return { error: getFriendlyErrorMessage(error) };

    await logLedgerEntry(supabase, {
      user_id: user.id,
      action_type: "BUDGET_UPSERT",
      amount: formData.amount,
      details: `Budget limit set for ${formData.category}: ₹${formData.amount.toLocaleString()} (${formData.period_month}/${formData.period_year})`,
      source_type: "budget",
      metadata: formData
    });

    revalidatePath("/dashboard/budget");
    return { success: true, message: "Upsert Budget successful" };
  } catch (err) {
    console.error("Error in upsertBudget:", err);
    return { error: getFriendlyErrorMessage(err) };
  }
}

export async function deleteBudget(id: string) {
  try {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return { error: "Unauthorized" };

    const { data, error } = await supabase.rpc("atomic_delete_entity", {
      p_user_id: user.id,
      p_entity_type: "budget",
      p_entity_id: id
    });

    if (error) return { error: getFriendlyErrorMessage(error) };
    const res = data as { success: boolean; error?: string } | null;
    if (!res?.success) return { error: res?.error || "Failed to delete budget atomically" };

    revalidatePath("/dashboard/budget");
    return { success: true, message: "Budget deleted successfully" };
  } catch (err) {
    console.error("Error in deleteBudget:", err);
    return { error: getFriendlyErrorMessage(err) };
  }
}

export async function copyPreviousMonthBudgets(
  fromMonth: number,
  fromYear: number,
  toMonth: number,
  toYear: number
) {
  try {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return { error: "Not authenticated" };

    // 1. Fetch source budgets
    const { data: sourceBudgets, error: fetchErr } = await supabase
      .from("budgets")
      .select("category,amount")
      .eq("user_id", user.id)
      .eq("period_month", fromMonth)
      .eq("period_year", fromYear);

    if (fetchErr) return { error: fetchErr.message };
    if (!sourceBudgets || sourceBudgets.length === 0) {
      return { error: "No budgets found in the previous period to carry over." };
    }

    // 2. Map payload
    const upsertData = sourceBudgets.map(b => ({
      user_id: user.id,
      category: b.category,
      amount: Number(b.amount),
      period_month: toMonth,
      period_year: toYear
    }));

    // 3. Upsert
    const { error: upsertErr } = await supabase
      .from("budgets")
      .upsert(upsertData, {
        onConflict: "user_id,category,period_month,period_year"
      });

    if (upsertErr) return { error: upsertErr.message };

    await logLedgerEntry(supabase, {
      user_id: user.id,
      action_type: "BUDGET_CARRY_OVER",
      details: `Carried over ${sourceBudgets.length} budget limits from ${fromMonth}/${fromYear} to ${toMonth}/${toYear}`,
      source_type: "budget",
      metadata: { fromMonth, fromYear, toMonth, toYear, count: sourceBudgets.length }
    });

    revalidatePath("/dashboard/budget");
    return { success: true, count: sourceBudgets.length };
  } catch (err) {
    console.error("Error in copyPreviousMonthBudgets:", err);
    return { error: getFriendlyErrorMessage(err) };
  }
}

export async function clearAllBudgets(month: number, year: number) {
  try {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return { error: "Not authenticated" };

    const { error } = await supabase
      .from("budgets")
      .delete()
      .eq("user_id", user.id)
      .eq("period_month", month)
      .eq("period_year", year);

    if (error) return { error: getFriendlyErrorMessage(error) };

    await logLedgerEntry(supabase, {
      user_id: user.id,
      action_type: "BUDGET_CLEAR",
      details: `Cleared all budget limits for ${month}/${year}`,
      source_type: "budget",
      metadata: { month, year }
    });

    revalidatePath("/dashboard/budget");
    return { success: true, message: "Clear All Budgets successful" };
  } catch (err) {
    console.error("Error in clearAllBudgets:", err);
    return { error: getFriendlyErrorMessage(err) };
  }
}

export async function setDefaultBudgets(month: number, year: number) {
  try {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return { error: "Not authenticated" };

    const defaultBudgets = [
      { category: "Rent", amount: 15000 },
      { category: "Food", amount: 8000 },
      { category: "Travel", amount: 4000 },
      { category: "Investment", amount: 10000 },
      { category: "Transport", amount: 3000 },
      { category: "Utilities", amount: 3000 },
      { category: "Entertainment", amount: 4000 },
      { category: "Shopping", amount: 5000 },
      { category: "Subscription", amount: 1500 },
      { category: "Others", amount: 2000 }
    ].map(b => ({
      user_id: user.id,
      category: b.category,
      amount: b.amount,
      period_month: month,
      period_year: year
    }));

    const { error } = await supabase
      .from("budgets")
      .upsert(defaultBudgets, {
        onConflict: "user_id,category,period_month,period_year"
      });

    if (error) return { error: getFriendlyErrorMessage(error) };

    await logLedgerEntry(supabase, {
      user_id: user.id,
      action_type: "BUDGET_DEFAULTS",
      details: `Set ${defaultBudgets.length} default category budget limits for ${month}/${year}`,
      source_type: "budget",
      metadata: { month, year, count: defaultBudgets.length }
    });

    revalidatePath("/dashboard/budget");
    return { success: true, count: defaultBudgets.length };
  } catch (err) {
    console.error("Error in setDefaultBudgets:", err);
    return { error: getFriendlyErrorMessage(err) };
  }
}
